// Alerta de PERDA SILENCIOSA na Amazon. Nasceu em 11/08/2026: este buraco estava classificado como limite
// declarado, e limite declarado e onde mora o que se decidiu NAO fazer.
//
// O QUE ELE VIGIA, e por que o alerta de 18h nao servia. Aquele pergunta "quando
// foi a ultima linha?" e existe para pegar COLETOR PARADO. Uma rodada em que 3 das
// 22 vitrines falharam GRAVA, e grava no horario certo: para ele, e uma rodada
// normal. A perda nao e de rodada, e de PEDACO de rodada.
//
// COMO ELE ACHA A LINHA DE ERRO: pelo item_id vazio, nao pelo texto do titulo.
// O invariante esta medido na serie exportada inteira, deduplicada por id (11/08):
// 59 linhas de erro, as 59 com item_id vazio, e ZERO linha de item_id vazio que
// nao seja erro -- reconferido em 24/08 na serie ate la: 82 de 82 nos dois
// sentidos. (Dizia 90: era o concat CRU dos 13 exports, que se sobrepoem. O
// invariante sempre esteve certo; o numero descrevia populacao duplicada.) E o
// mesmo invariante que a Silver usa para descartar essas linhas.
// E o operador foi MEDIDO, nao suposto (sonda de 11/08, execucao 3248): no no
// dataTable, 'isEmpty' casa NULO -- 'eq' com string vazia nao casa nada.
//
// ATENCAO: SEM executeOnce NOS NOS ACIMA E AQUI, E ISSO NAO E DESCUIDO. Copiei o flag do
// alerta de coletor parado, onde cada leitura traz UMA linha e ele nunca mordeu.
// Aqui ele truncava a leitura na PRIMEIRA linha: com 3 vitrines em erro, o alerta
// diria "1 vitrine(s) em erro" -- confiante e errado. Pego pelo teste com dado
// pinado em 11/08 (execucao 3249), que injetou 4 linhas e viu chegar 1.
//
// O ENVIO FOI PROVADO em 11/08 (execucao 3256): um rascunho temporario injetou uma
// vitrine ficticia so para o Filtro deixar passar, e o evolution-api aceitou a
// mensagem (fromMe: true). O rascunho foi desfeito no mesmo minuto -- esta versao
// NAO tem bloco de teste nenhum, e e a que esta publicada. Sem esse disparo, a
// credencial ficaria sem prova ate o primeiro episodio real, que e justamente o
// dia em que nao se quer descobrir que ela esta errada.
//
// JANELA DE 24h EM VEZ DE MEMORIA. A Amazon coleta 12/12h. Rodando 1x por dia,
// depois da segunda rodada, uma janela de 24h cobre as duas -- e o workflow nao
// precisa guardar o que ja avisou. Vigia sem memoria nao tem como mentir sobre o
// que ja disse. (Alternativas descartadas em 11/08: avisar a cada rodada, que
// dispararia em ~30% delas, e limiar >=3 vitrines, que perderia a maioria dos
// casos, porque a maioria e de 1 a 2 vitrines.)
//
// ATENCAO: A JANELA CONVERSA COM A PURGA, e a margem foi conferida: o backup diario
// purga a tabela as 15:00 BRT (18:00 UTC) deixando so o snapshot mais recente.
// Este alerta roda as 12:20 BRT (15:20 UTC), 2h40 ANTES da purga, e a essa hora a
// tabela tem as duas rodadas do dia (03:00 e 15:00 UTC) mais a de 15:00 do dia
// anterior, que a janela de 24h exclui por 20 minutos. Mover qualquer um dos dois
// horarios mexe nessa margem.
//
// ESTE NO SEMPRE EMITE O QUE VIU, inclusive zero vitrine em erro -- quem decide
// avisar e o Filtro seguinte. Monitor que devolve [] quando esta tudo bem e
// indistinguivel de monitor morto (regra do projeto, nascida em 25/07).
//
// O QUE ELE NAO FAZ: traduzir rotulo -> slug. Esse mapa e versionado, mora no
// 03_Analise/amazon_vitrines_inventario.py, e copia-lo para ca criaria uma segunda
// copia que envelhece sozinha. A mensagem aponta para o script que traduz.
const NL = String.fromCharCode(10);
const JANELA_H = 24;
const LIMIAR_VITRINES = 1;
const agora = Date.now();
const recentes = [];
let lidas = 0;
for (const item of $input.all()) {
  const j = item.json || {};
  if (!j.coletado_em) { continue; }
  lidas = lidas + 1;
  const idadeH = (agora - new Date(j.coletado_em).getTime()) / 3600000;
  if (idadeH <= JANELA_H) { recentes.push(j); }
}
const porVitrine = {};
const rodadas = {};
for (const r of recentes) {
  const nome = r.categoria_pagina || "(sem categoria)";
  if (!porVitrine[nome]) { porVitrine[nome] = { vitrine: nome, ocorrencias: 0, ultima_rodada: null, ultimo_motivo: null }; }
  porVitrine[nome].ocorrencias = porVitrine[nome].ocorrencias + 1;
  if (!porVitrine[nome].ultima_rodada || r.coletado_em > porVitrine[nome].ultima_rodada) {
    porVitrine[nome].ultima_rodada = r.coletado_em;
    porVitrine[nome].ultimo_motivo = r.titulo || null;
  }
  rodadas[r.coletado_em] = true;
}
const vitrines = [];
for (const nome of Object.keys(porVitrine)) { vitrines.push(porVitrine[nome]); }
vitrines.sort(function (a, b) { return a.vitrine < b.vitrine ? -1 : 1; });
const nRodadas = Object.keys(rodadas).length;
const alertar = vitrines.length >= LIMIAR_VITRINES;
let txt = "";
if (alertar) {
  txt = "*ENXAME - perda silenciosa na Amazon*" + NL + NL;
  txt = txt + "Nas ultimas " + JANELA_H + "h: " + vitrines.length + " vitrine(s) em erro, em " + nRodadas + " rodada(s)." + NL + NL;
  for (const v of vitrines) {
    const quando = v.ultima_rodada ? v.ultima_rodada.slice(0, 16).replace("T", " ") + " UTC" : "?";
    txt = txt + "- " + v.vitrine + " (" + v.ocorrencias + "x, ultima " + quando + ")" + NL;
  }
  txt = txt + NL + "Motivo gravado: " + (vitrines[0].ultimo_motivo || "?") + NL;
  txt = txt + "A rodada GRAVOU: o alerta de 18h nao pega isto." + NL;
  txt = txt + "Para sondar as vitrines: python 03_Analise/vitrines_amazon_em_erro.py";
}
return [{ json: {
  alertar: alertar,
  resumo: alertar ? vitrines.length + " vitrine(s) em erro em " + JANELA_H + "h" : "nenhuma vitrine em erro na janela, nada a enviar",
  janela_horas: JANELA_H,
  limiar_vitrines: LIMIAR_VITRINES,
  linhas_de_erro_lidas: lidas,
  linhas_de_erro_na_janela: recentes.length,
  rodadas_afetadas: nRodadas,
  verificado_em: new Date().toISOString(),
  vitrines: vitrines,
  mensagem: txt
} }];
